Here's a focused test module covering the key correctness properties: no lost writes, no lost upserts under contention, no torn reads, and disjoint-key isolation. Drop it next to the `ShardedMap` definition.

```rust
#[cfg(test)]
mod concurrency_tests {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::thread;

    /// Many writers on disjoint key ranges, plus readers polling the whole
    /// keyspace. Every value present must satisfy the invariant `v == k * 2`,
    /// which catches torn reads, mis-routed shards, or value corruption.
    #[test]
    fn parallel_writes_and_reads() {
        const WRITERS: u64 = 8;
        const KEYS_PER_WRITER: u64 = 5_000;
        const READERS: usize = 8;
        const TOTAL: u64 = WRITERS * KEYS_PER_WRITER;

        let map: Arc<ShardedMap<u64, u64>> = Arc::new(ShardedMap::with_shards(32));
        let stop = Arc::new(AtomicBool::new(false));

        let readers: Vec<_> = (0..READERS)
            .map(|seed| {
                let map = map.clone();
                let stop = stop.clone();
                thread::spawn(move || {
                    // Cheap, deterministic-per-thread PRNG so each reader
                    // probes a different stream of keys.
                    let mut s = 0xC0FFEE_u64.wrapping_add(seed as u64);
                    while !stop.load(Ordering::Relaxed) {
                        s ^= s << 13;
                        s ^= s >> 7;
                        s ^= s << 17;
                        let k = s % TOTAL;
                        if let Some(v) = map.get(&k) {
                            assert_eq!(v, k * 2, "invariant broken at key {k}");
                        }
                    }
                })
            })
            .collect();

        let writers: Vec<_> = (0..WRITERS)
            .map(|w| {
                let map = map.clone();
                thread::spawn(move || {
                    let start = w * KEYS_PER_WRITER;
                    for k in start..start + KEYS_PER_WRITER {
                        map.insert(k, k * 2);
                    }
                })
            })
            .collect();

        for h in writers { h.join().unwrap(); }
        stop.store(true, Ordering::Relaxed);
        for h in readers { h.join().unwrap(); }

        // Every key inserted must be present with the right value.
        assert_eq!(map.len() as u64, TOTAL);
        for k in 0..TOTAL {
            assert_eq!(map.get(&k), Some(k * 2), "missing/wrong key {k}");
        }
    }

    /// Hammered contention on a single key. If `upsert` is non-atomic
    /// (e.g. read-then-write under separate locks), increments are lost
    /// and the final count drops below the expected total.
    #[test]
    fn parallel_upsert_counter() {
        const THREADS: usize = 16;
        const ITERS: u64 = 10_000;

        let map: Arc<ShardedMap<&'static str, u64>> = Arc::new(ShardedMap::new());
        let handles: Vec<_> = (0..THREADS)
            .map(|_| {
                let map = map.clone();
                thread::spawn(move || {
                    for _ in 0..ITERS {
                        map.upsert("counter", 1, |v| *v += 1);
                    }
                })
            })
            .collect();
        for h in handles { h.join().unwrap(); }

        assert_eq!(map.get(&"counter"), Some(THREADS as u64 * ITERS));
    }

    /// Each thread runs a full insert -> get -> remove -> get cycle on its
    /// own disjoint key range. Operations on one thread's keys must not be
    /// observable as side effects on another's, and the map must be empty
    /// at the end.
    #[test]
    fn disjoint_lifecycle_isolation() {
        const THREADS: u64 = 8;
        const OPS: u64 = 2_000;

        let map: Arc<ShardedMap<u64, u64>> = Arc::new(ShardedMap::new());
        let handles: Vec<_> = (0..THREADS)
            .map(|t| {
                let map = map.clone();
                thread::spawn(move || {
                    for i in 0..OPS {
                        let k = t * OPS + i;
                        assert_eq!(map.insert(k, k + 1), None);
                        assert_eq!(map.get(&k), Some(k + 1));
                        assert_eq!(map.remove(&k), Some(k + 1));
                        assert_eq!(map.get(&k), None);
                    }
                })
            })
            .collect();
        for h in handles { h.join().unwrap(); }

        assert_eq!(map.len(), 0);
    }

    /// Concurrent insert + remove on the same key range. After all threads
    /// finish, every surviving key must still satisfy the value invariant.
    #[test]
    fn parallel_insert_and_remove_same_range() {
        const KEYS: u64 = 4_000;
        const WORKERS: usize = 8;

        let map: Arc<ShardedMap<u64, u64>> = Arc::new(ShardedMap::new());

        let handles: Vec<_> = (0..WORKERS)
            .map(|w| {
                let map = map.clone();
                thread::spawn(move || {
                    for k in 0..KEYS {
                        if w % 2 == 0 {
                            map.insert(k, k * 2);
                        } else {
                            map.remove(&k);
                        }
                    }
                })
            })
            .collect();
        for h in handles { h.join().unwrap(); }

        // Whatever survived must still be valid.
        for k in 0..KEYS {
            if let Some(v) = map.get(&k) {
                assert_eq!(v, k * 2, "corrupted value at {k}");
            }
        }
    }
}
```

What each test pins down:

- `parallel_writes_and_reads` — readers and writers run simultaneously; verifies no torn reads and that every disjoint write lands.
- `parallel_upsert_counter` — stress on a single shard and key; verifies `upsert` is atomic (no lost increments).
- `disjoint_lifecycle_isolation` — full insert/get/remove cycles on disjoint ranges; verifies threads don't observe each other's keys.
- `parallel_insert_and_remove_same_range` — overlapping insert/remove traffic; verifies no value corruption regardless of who wins.

Run with `cargo test` for a quick check, or `cargo test --release -- --test-threads=1` for heavier stress on a single test at a time. For deeper concurrency coverage you'd reach for [`loom`](https://docs.rs/loom) to model-check the interleavings, but these stochastic tests are usually enough to catch the obvious correctness regressions.
